struct QueryListAndUtilitySourceContractTests {
    @Test func queryListPagesKeepInternalScrollWithoutWrappingEmptyResults() throws {
        let deviceInfo = try readSource("Sources/XTools/ToolPages/Utility/DeviceInformationPage.swift")
        let httpStatus = try readSource("Sources/XTools/ToolPages/Web/HTTPStatusCodesPage.swift")
        let timezone = try readSource("Sources/XTools/ToolPages/Time/TimezoneViewerPage.swift")
        let emoji = try readSource("Sources/XTools/ToolPages/Utility/EmojiPickerPage.swift")
        let emojiCollection = try readSource("Sources/XTools/ToolPages/Utility/EmojiCollectionView.swift")

        contains(deviceInfo, "workspaceSemantic: .queryListWorkspace", "Device information must use the query-list page shell")
        contains(deviceInfo, "IndexPanel(\"macOS 设备信息\") {\n                ScrollView {\n                    IndexKV(rows: rows, emptyText: \"加载设备信息中…\", copyable: true)", "Device information must keep its fixed information list in a panel-local scroll view")
        contains(deviceInfo, ".verticallyFilling()", "Device information query/list panel must fill the available workspace")

        contains(httpStatus, "IndexPanel(\"状态码（\\(filtered.count)）\") {\n                if filtered.isEmpty {\n                    emptyState\n                } else {\n                    List(filtered) { row in", "HTTP status must keep empty results outside its native list and render non-empty results through the internal list owner")
        contains(httpStatus, ".listStyle(.plain)", "HTTP status must use the native plain list virtualization path")
        contains(httpStatus, ".scrollContentBackground(.hidden)", "HTTP status native list must preserve the panel visual surface")
        doesNotContain(httpStatus, "LazyVStack(spacing: 0)", "HTTP status must not eagerly materialize every status row through the nested lazy stack path")
        contains(httpStatus, ".verticallyFilling()", "HTTP status query/list panel must fill the available workspace")

        contains(timezone, "IndexPanel(\"时区列表\") {\n                ScrollView {\n                    VStack(spacing: ToolMetrics.Spacing.lg)", "Timezone viewer must keep its browsable timezone list in a panel-local scroll view")
        contains(timezone, ".frame(maxWidth: .infinity, maxHeight: .infinity)", "Timezone internal list scroll view must fill the result panel")
        contains(timezone, ".verticallyFilling()", "Timezone query/list panel must fill the available workspace")

        contains(emoji, "if entries.isEmpty {\n            IndexEmptyState(", "Emoji empty search results must render the shared empty state before the collection renderer")
        contains(emoji, "} else {\n            IndexEmojiCollectionView(", "Emoji non-empty browse/search results must use the panel-local native collection renderer")
        contains(emoji, "private func specialSymbolSections(_ sections: [EmojiSection]) -> some View", "Emoji special-symbol browse mode must render catalog-owned sections")
        contains(emojiCollection, "static func sectioned(sections: [EmojiSection]", "Emoji special-symbol browse mode must project catalog sections into native collection sections")
        contains(emojiCollection, "groupTitle: subsectionIndex == 0 ? section.name : nil", "Emoji section projection must retain parent section headings")
        doesNotContain(emoji, "ToolDisclosureBody", "Emoji special-symbol browse mode must not add collapsible section state for the MVP")
        contains(emoji, ".verticallyFilling()", "Emoji query/list panel must fill the available workspace")

        for page in [deviceInfo, httpStatus, timezone, emoji] {
            doesNotContain(page, "IndexWorkspaceResultSurface(workspaceSemantic: .naturalHeightShortResultPanel)", "Query/list workspaces must not be reclassified as natural-height short result panels")
            doesNotContain(page, "IndexShortResultKV(", "Query/list workspaces must not reuse short-result KV semantics")
            doesNotContain(page, "IndexShortResultCardList(", "Query/list workspaces must not reuse short-result card semantics")
        }
    }

    @Test func deviceInformationKeepsOnlyUsefulDebugRowsAndCopyActions() throws {
