        contains(session, "@Published private(set) var snapshot: DeviceInformationSnapshot", "Device information session must expose a read-only snapshot")
        contains(session, "func refresh()", "Device information session must expose one explicit refresh command")

        doesNotContain(implementation, "\"活跃核心\"", "Device information must not include active-core noise")
        doesNotContain(implementation, "\"温控状态\"", "Device information must not include thermal-state noise")
        doesNotContain(implementation, "thermalStateName(", "Device information must not keep unused thermal-state formatting")
        doesNotContain(implementation, "localNetworkAddress(interfaceName: \"en0\", family: .ipv4)", "Device information must not hard-code en0")
        doesNotContain(implementation, "localNetworkRows", "Device information must not list every local network interface")

        doesNotContain(implementation, "\"降低动态效果\"", "Device information must not include accessibility preference noise")
        doesNotContain(implementation, "\"降低透明度\"", "Device information must not include accessibility preference noise")
        doesNotContain(implementation, "\"增强对比度\"", "Device information must not include accessibility preference noise")
        doesNotContain(implementation, "\"低电量模式\"", "Device information must not include low-power mode")
        doesNotContain(implementation, "\"App 版本\"", "Device information must not include app version")
        doesNotContain(implementation, "\"Bundle ID\"", "Device information must not include bundle id")
        doesNotContain(implementation, "\"缩放因子\"", "Device information must not include standalone scale factor")
        doesNotContain(implementation, "\"外观\"", "Device information must not include appearance")
        doesNotContain(implementation, "\"进程 ID\"", "Device information must not include process id")
        doesNotContain(implementation, "\"Darwin 内核\"", "Device information must not include Darwin kernel")
        doesNotContain(implementation, "\"语言\"", "Device information must not include language")
        doesNotContain(implementation, "\"日历\"", "Device information must not include calendar")
        doesNotContain(implementation, "\"主屏幕逻辑尺寸\"", "Device information must not include logical screen size")
        doesNotContain(implementation, "\"可用区域\"", "Device information must not include visible frame")
        doesNotContain(implementation, "\"色彩空间\"", "Device information must not include color space")
    }

    @Test func utilityPagesDelegateToCoreLogicAndBoundRendering() throws {
        let math = try readSource("Sources/XTools/ToolPages/Utility/MathEvaluatorPage.swift")
        let textStats = try readSource("Sources/XTools/ToolPages/Utility/TextStatisticsPage.swift")
        let textStatsModel = try readSource("Sources/XTools/ToolPages/Utility/TextStatisticsWorkspaceModel.swift")
        let emoji = try readSource("Sources/XTools/ToolPages/Utility/EmojiPickerPage.swift")
        let emojiCollection = try readSource("Sources/XTools/ToolPages/Utility/EmojiCollectionView.swift")
        let fileType = try readSource("Sources/XTools/ToolPages/Utility/FileTypeDetectorPage.swift")
        let fileTypeSession = try readSource("Sources/XTools/ToolPages/Utility/FileTypeDetectorSession.swift")

        contains(math, "MathExpressionEvaluator.evaluateLiveInput(trimmed)", "Math page must delegate live expression classification to Core")
        contains(math, ".indexWorkspaceDiagnostic(diagnosticText)", "Math page diagnostics must use the shared non-displacing workspace anchor")
        doesNotContain(math, "mathDiagnosticAccessory", "Math page must not hand-build title-accessory diagnostics that squeeze the header")
        doesNotContain(math, "ToolFeedbackTone.error.systemImage", "Math page must not hand-build persistent error labels")
        doesNotContain(math, ".accessibilityLabel(\"错误：", "Math page must rely on the shared diagnostic accessibility label")
        doesNotContain(math, "mathFeedbackSlot", "Math page must not reserve body space for live validation feedback")
        doesNotContain(math, ".frame(maxWidth: .infinity, minHeight: 50, alignment: .topTrailing)", "Math page must not keep a large empty feedback slot below the input")
        doesNotContain(math, "NSExpression", "Math page must not evaluate expressions through Foundation's dynamic expression engine")
        doesNotContain(math, "JavaScriptCore", "Math page must not evaluate expressions through a script engine")

        doesNotContain(textStats, "TextStatistics.analyze(", "Text statistics View body must not run Unicode-aware analysis on the main actor")
        contains(textStatsModel, "TextStatistics.analyze(input, shouldCancel: shouldCancel)", "Text statistics background model must delegate cancellable Unicode-aware counting to Core")
        contains(textStatsModel, "SupersedingExecutionSession(cancelInFlight: true)", "Text statistics analysis must use the shared serial latest-wins worker")
        contains(textStats, "workspaceSemantic: .fixedInputWorkspace", "Text statistics must preserve the fixed-input workspace semantic")
        contains(textStats, "TextStatisticsAnalysisStatus(isAnalyzing: workspace.isAnalyzing)", "Text statistics must expose analysis state in the statistics panel header")
        contains(textStats, "valueMotion: .immediate", "Text statistics values must remain immediate rather than animating each completion")
        doesNotContain(textStats, "IndexProgressMotionLabel", "Text statistics loading feedback must not add animated text or icon swaps")

        contains(fileTypeSession, "FileTypeDetector.inspect(", "File type session must delegate evidence resolution, size, and header interpretation to Core")
        contains(fileTypeSession, "read(upToCount: maxByteCount)", "File type reader must keep file reads bounded to the detector prefix limit supplied by the session")
        contains(fileTypeSession, "maxByteCount: FileTypeDetector.leadingByteLimit", "File type session must request only the Core detector prefix limit")
        doesNotContain(fileType, "FileTypeDetector.inspect(", "File type page must leave report construction in the session")
        doesNotContain(fileType, "FileHandle(forReadingFrom:", "File type page must not read selected files on the main actor")

        contains(emoji, "\"Emoji 与符号\"", "Emoji page title must reflect that it now includes symbols")
        contains(emoji, "EmojiCatalog.specialSymbolCount", "Emoji page subtitle must count unique special symbols separately")
        contains(emoji, "private static let displayLimit = 200", "Emoji page must cap broad search rendering for predictable grid performance")
        contains(emoji, "EmojiCatalog.search(matching: query, limit: Self.displayLimit)", "Emoji search must use Core's structured capped result")
        contains(emojiCollection, "EmojiCatalog.apply(tone: tone, to: entry)", "Emoji renderer must delegate skin-tone application to Core")
        contains(emoji, "var showsSkinToneControl: Bool", "Emoji tone visibility must be explicit result capability state")
        contains(emoji, "entries.contains(where: \\.skinToneCapable)", "Emoji tone visibility must follow current result capability rather than a category-name whitelist")
        let emojiActionBar = sourceSlice(emoji, from: "IndexActionBar {", to: "if !display.isSearching")
        doesNotContain(emojiActionBar, "skinToneControl", "The global search bar must not retain a tone control that appears valid for every category")
        doesNotContain(emojiActionBar, "autoFocus: true", "Emoji search must wait for an explicit click instead of blinking the caret on page entry")
        let emojiPanel = sourceSlice(emoji, from: "IndexPanel(display.panelTitle)", to: ".verticallyFilling()")
        contains(emojiPanel, "panelAccessory(for: display)", "The result panel header must own its contextual accessory")
        let emojiPanelAccessory = sourceSlice(emoji, from: "private func panelAccessory(for display: DisplayState)", to: "private func emojiGrid")
        contains(emojiPanelAccessory, "if display.isTruncated", "The result panel header must disclose capped search results")
        contains(emojiPanelAccessory, "仅展示前 200 个结果", "The result panel header must state the visible search limit")
        contains(emojiPanelAccessory, "if display.showsSkinToneControl", "The result panel header must reveal tone options only for capable results")
        contains(emojiPanelAccessory, "skinToneControl", "The result panel header must own the tone selector")
        contains(emoji, "density: .compact", "The six-option Emoji tone selector must use the compact shared segmented-control density")
        contains(emojiCollection, "helpText: entry.helpText(for: glyph)", "Emoji native cells must retain exact rendered-glyph help text")
    }

