        doesNotContain(color, "autoFocus: true", "Color page must not trigger AppKit autofocus during tool entry")
        contains(color, "@State private var showsSystemColorPicker = false", "Color page must keep system ColorPicker behind an explicit on-demand state")
        contains(color, ".popover(isPresented: $showsSystemColorPicker", "Color page must mount the system ColorPicker only when the picker popover is requested")
        contains(color, "private var systemColorPicker: some View", "Color page must keep the deferred system ColorPicker in a named helper")
        let pickerBody = sourceSlice(color, from: "private var pickerBody: some View", to: "private var systemColorPicker: some View")
        doesNotContain(pickerBody, "ColorPicker(", "Color page first paint must not directly mount the system ColorPicker inside pickerBody")
        let systemColorPicker = sourceSlice(color, from: "private var systemColorPicker: some View", to: "private func hslBinding")
        contains(systemColorPicker, "ColorPicker(", "Color page must preserve system ColorPicker capability inside the on-demand helper")
        contains(systemColorPicker, "supportsOpacity: true", "System color picking must preserve Alpha")
        contains(color, "IndexDisclosure(", "Advanced color spaces must stay bounded behind the shared disclosure component")
        doesNotContain(color, "DisclosureGroup(", "Color disclosure must not regress to the arrow-only system hit target")
        contains(color, "IndexBadge(\"映射到 sRGB\", tone: .warning)", "Legacy display formats must visibly disclose gamut mapping through the shared warning badge")
        contains(color, "title: \"复制 \\(value.label)\"", "Every color result must expose a format-specific copy label")
        contains(color, "accessibilityName: \"Alpha 透明度\"", "Alpha must remain keyboard and VoiceOver adjustable")
        doesNotContain(color, "suppressNextHexSync", "The canonical reducer must not retain the old one-shot feedback-loop flag")

        contains(userAgent, "UserAgentParser.validationIssue(trimmed)", "UserAgent page must distinguish empty input from structurally invalid input")
        contains(userAgent, "error = userAgentErrorMessage(for: UserAgentParser.validationIssue(trimmed))", "UserAgent page must surface structurally invalid strings instead of silently clearing results")
        contains(userAgent, ".indexWorkspaceDiagnostic(workspace.error)", "UserAgent retained errors must use the non-displacing workspace anchor")
        occurrenceCount(userAgent, ".indexWorkspaceDiagnostic(workspace.error)", 1, "UserAgent must expose one retained input-owned error diagnostic")
        appearsBefore(userAgent, ".indexWorkspaceDiagnostic(workspace.error)", "IndexPanel(\"解析结果\")", "UserAgent errors must belong to the input panel rather than the result panel")

        let basicAuthSession = try readSource("Sources/XToolsCore/Web/BasicAuthWorkspaceSession.swift")
        contains(basicAuthSession, "public var outputDiagnostic: String?", "Basic Auth must promote invalid credential states to a persistent diagnostic in the Core session")
        contains(basicAuth, ".indexWorkspaceDiagnostic(session.outputDiagnostic)", "Basic Auth invalid credentials must use the non-displacing workspace anchor")
    }

