        doesNotContain(page, "魔数", "File type UI must not describe every displayed header byte as a magic number")
        appearsBefore(page, "IndexKVRow(key: \"文件名\"", "IndexKVRow(key: \"文件扩展名\"", "File name must stay before extension")
        appearsBefore(page, "IndexKVRow(key: \"文件扩展名\"", "IndexKVRow(key: \"扩展名推断 MIME\"", "Actual extension must stay before extension evidence")
        appearsBefore(page, "IndexKVRow(key: \"扩展名推断 MIME\"", "IndexKVRow(key: \"内容签名 MIME\"", "Extension evidence must stay before content evidence")
        appearsBefore(page, "IndexKVRow(key: \"内容签名 MIME\"", "IndexKVRow(key: \"最终判定 MIME\"", "Content evidence must stay before the resolved type")
        appearsBefore(page, "IndexKVRow(key: \"最终判定 MIME\"", "IndexKVRow(key: \"文件大小\"", "Resolved type must stay before file size")
        appearsBefore(page, "IndexKVRow(key: \"文件大小\"", "IndexKVRow(key: \"文件头（前 16 字节）\"", "File size must stay before header bytes")

        contains(sharedComponents, "var valueLineBreakMode: NSLineBreakMode? = .byCharWrapping", "Result rows must wrap long content values by default")
        contains(sharedComponents, "Text(indexWrappingAttributedText(value, lineBreakMode: valueLineBreakMode))", "Result rows must support explicit long-token wrapping")
        contains(sharedComponents, "Text(value)", "Result rows must preserve an explicit nil fallback for plain text rendering")
        contains(sharedComponents, ".fixedSize(horizontal: false, vertical: true)", "Wrapped result values must expand to their natural row height")
    }

